<?php
$programUid=(int)current_user()['id'];$programPrefs=comm_get('planner.preferences.'.$programUid,['timezone'=>'Africa/Nairobi']);$programDate=(new DateTimeImmutable('now',comm_zone($programPrefs['timezone'])))->format('Y-m-d');$programAll=planner_day($programUid,$programDate,$programPrefs['timezone']);$programRows=array_values(array_filter($programAll,static fn($r)=>!in_array($r['status'],['cancelled','completed'],true)));$programDone=array_values(array_filter($programAll,static fn($r)=>in_array($r['status'],['cancelled','completed'],true)));$programSnapshot=comm_get('planner.calendar.'.$programUid);$programDeviceCount=count(array_filter(comm_user_devices($programUid),static fn($d)=>!empty($d['enabled'])));$programNotify=comm_get('preferences.'.$programUid,comm_preferences([]));
?>
<link rel="stylesheet" href="<?=asset('css/program.css')?>">
<section class="program-card program-home" aria-label="Daily program"><div class="program-head"><div><span class="writer-kicker"><?=e($programDate.' · '.$programPrefs['timezone'])?></span><h2>Today’s activities & program</h2><p><?=count($programRows)?> active · <?=count($programDone)?> completed or cancelled · meetings, projects and personal commitments.</p></div><a class="wbtn primary" href="<?=url('/write/program')?>">Open daily program</a></div>
<div class="program-actions"><a class="wbtn" href="<?=url('/write/program?date='.$programDate)?>">Add or change an activity</a><a class="wbtn" href="<?=url('/write/voice')?>">Capture voice notes</a><a class="wbtn" href="<?=url('/write/app')?>"><?=!empty($programNotify['enabled'])&&$programDeviceCount?'Reminders · '.$programDeviceCount.' device(s)':'Enable phone / computer reminders'?></a></div><p class="program-meta">Reminder sequence: <?=($programPrefs['reminder_sequence']??'single')==='staggered'?'chosen lead, five minutes, start time':'one reminder'?>. Entries with reminders off stay silent.</p>
<?php if(empty($programSnapshot['observed'])):?><p class="program-warning">Connected calendar snapshot has not been loaded. Open the daily program to refresh it.</p><?php else:?><p class="program-meta">Calendar snapshot: <?=e(date('j M H:i T',$programSnapshot['observed']))?>. <?=!empty($programSnapshot['errors'])?'Some calendars need attention.':''?></p><?php endif;?>
<?php if(!$programRows):?><p>No active activities for today. Add your plan or refresh connected calendars.</p><?php else:?><div class="program-home-list"><?php foreach(array_slice($programRows,0,30)as$r):$ongoing=$r['start']<=time()&&$r['end']>time();$earlier=$r['end']<=time();?><article class="program-item"><time><?=e((new DateTimeImmutable('@'.$r['start']))->setTimezone(comm_zone($programPrefs['timezone']))->format('H:i'))?>–<?=e((new DateTimeImmutable('@'.$r['end']))->setTimezone(comm_zone($programPrefs['timezone']))->format('H:i'))?></time><span class="program-pill"><?=$ongoing?'Now':($earlier?'Earlier today':'Upcoming')?></span><h3><?=e($r['title'])?></h3><small><?=e($r['source'].' · '.$r['status'])?><?=!empty($r['stale'])?' · last known event; refresh required':''?></small><div class="program-actions"><?php if(!empty($r['join'])):?><a class="wbtn" target="_blank" rel="noopener noreferrer" href="<?=e($r['join'])?>">Join meeting</a><?php endif;?><?php if($r['source']==='program'):?><a href="<?=url('/write/program?date='.$programDate.'&edit='.$r['id'])?>">Edit activity</a><?php elseif($r['source']==='booking'):?><a href="<?=url('/write/booking-review?id='.$r['id'])?>">Review or change booking</a><?php else:?><a href="<?=url('/write/program?date='.$programDate)?>">Open program</a><?php endif;?></div></article><?php endforeach;?></div><?php if(count($programRows)>30):?><p><a href="<?=url('/write/program')?>">See all <?=count($programRows)?> activities</a></p><?php endif;?><?php endif;?>
<?php if($programDone):?><details><summary>Completed & cancelled · <?=count($programDone)?></summary><?php foreach(array_slice($programDone,0,30)as$r):?><p><?=e($r['title'].' · '.$r['status'])?></p><?php endforeach;?></details><?php endif;?></section>
